<?php
require __DIR__.'/includes/bootstrap.php';require_login();
$pid=teacher_program_id();$cycle=teacher_cycle();[$scope,$params]=assigned_scope('s');
$q=db()->prepare("SELECT COUNT(*) total,COALESCE(SUM(s.estado='Activo'),0) activos,COALESCE(SUM(s.nivel_riesgo='Alto' AND s.estado='Activo'),0) alto,COALESCE(SUM(s.nivel_riesgo='Medio' AND s.estado='Activo'),0) medio FROM students s WHERE 1=1".$scope);$q->execute($params);$stats=$q->fetch();
$q=db()->prepare("SELECT COALESCE(ROUND(AVG(s.asistencia)),0) asistencia_media,COALESCE(SUM(s.estado_socioemocional='Alerta'),0) alertas_emocionales FROM students s WHERE s.estado='Activo'".$scope);$q->execute($params);$extra=$q->fetch();
$q=db()->prepare("SELECT COUNT(*) FROM interventions i JOIN students s ON s.id=i.student_id WHERE i.fecha>=? AND i.fecha<?".$scope);$monthStart=date('Y-m-01');$nextMonth=date('Y-m-01',strtotime('+1 month'));$q->execute([$monthStart,$nextMonth,...$params]);$att=(int)$q->fetchColumn();
$personalTeacher=!is_coordinator()&&is_teacher();
$q=db()->prepare("SELECT p.nombre_corto nombre,COUNT(s.id) total,COALESCE(SUM(s.nivel_riesgo='Alto' AND s.estado='Activo'),0) alertas FROM programs p LEFT JOIN students s ON s.program_id=p.id".($pid?' AND s.academic_period=?'.($personalTeacher?' AND s.ciclo=? AND s.assigned_teacher_id=?':'').' WHERE p.id=?':' AND s.academic_period=?')." GROUP BY p.id ORDER BY p.id");$q->execute($pid?array_merge([teacher_period()],$personalTeacher?[$cycle,(int)current_user()['id']]:[],[$pid]):[active_period_code()]);$programs=$q->fetchAll();
$q=db()->prepare("SELECT i.fecha,i.tipo,i.estado,s.id student_id,CONCAT(s.nombres,' ',s.apellidos) estudiante,u.name responsable FROM interventions i JOIN students s ON s.id=i.student_id JOIN users u ON u.id=i.user_id WHERE 1=1".$scope." ORDER BY i.fecha DESC,i.id DESC LIMIT 10");$q->execute($params);$recent=$q->fetchAll();
$q=db()->prepare("SELECT s.id,s.codigo,CONCAT(s.nombres,' ',s.apellidos) estudiante,s.nivel_riesgo,s.asistencia FROM students s WHERE s.estado='Activo' AND s.nivel_riesgo='Alto'".$scope." ORDER BY s.asistencia ASC LIMIT 4");$q->execute($params);$alerts=$q->fetchAll();
$q=db()->prepare("SELECT DATE_FORMAT(i.fecha,'%Y-%m') periodo,COUNT(*) total FROM interventions i JOIN students s ON s.id=i.student_id WHERE i.fecha>=?".$scope." GROUP BY DATE_FORMAT(i.fecha,'%Y-%m')");$q->execute([date('Y-m-01',strtotime('-5 months')),...$params]);$trendRows=$q->fetchAll();$trendByMonth=array_column($trendRows,'total','periodo');
$months=[];$values=[];for($n=5;$n>=0;$n--){$date=strtotime("-$n months");$key=date('Y-m',$date);$months[]=ucfirst(date('M', $date));$values[]=(int)($trendByMonth[$key]??0);}
$maxTrend=max(1,max($values));$points=[];foreach($values as $i=>$value){$x=40+$i*90;$y=170-$value/$maxTrend*125;$points[]=round($x,1).','.round($y,1);}
$polyline=implode(' ',$points);$area='40,170 '.$polyline.' 490,170';$low=max(0,(int)$stats['total']-(int)$stats['alto']-(int)$stats['medio']);$maxProgram=max(1,...array_map('intval',array_column($programs,'total')));
$personalStats=null;if(is_combined_role()){$st=db()->prepare("SELECT COUNT(*) total,COALESCE(SUM(nivel_riesgo='Alto'),0) alto FROM students WHERE assigned_teacher_id=? AND academic_period=? AND ciclo=? AND deleted_at IS NULL");$st->execute([(int)current_user()['id'],teacher_period(),teacher_cycle()]);$personalStats=$st->fetch();}
$dashboardDescription=is_admin()?'Indicadores de bienestar y seguimiento estudiantil.':(is_combined_role()?'Vista de coordinación del programa · '.teacher_period().' · Indicadores del programa.':(is_teacher()?teacher_cycle().' ciclo · ':'').teacher_period().' · Indicadores de su asignación.');
$pageTitle='Panel de bienestar';$active='dashboard';include __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow">VISTA GENERAL · <?=e(date('Y'))?></span><h2><?=is_admin()?'Resumen institucional':(is_coordinator()?'Mi programa de estudios':'Mi grupo de consejería')?></h2><p><?=e($dashboardDescription)?></p></div><?php if(!is_coordinator()):?><a class="btn btn-primary" href="<?=url('modules/students.php?new=1')?>">+ Registrar estudiante</a><?php endif;?></div>
<?php if($personalStats):?><section class="panel combined-role-summary"><div><span class="eyebrow dark">MI LABOR COMO DOCENTE CONSEJERO</span><h3>Ciclo <?=e(teacher_cycle())?> · <?=e(teacher_period())?></h3><p><b><?=(int)$personalStats['total']?></b> estudiantes asignados · <b><?=(int)$personalStats['alto']?></b> con riesgo alto.</p></div><div class="actions"><a class="btn btn-secondary" href="<?=url('modules/students.php?mine=1')?>">Ver mis estudiantes</a><a class="btn btn-primary" href="<?=url('modules/reassignments.php')?>">Reasignar mis casos</a></div></section><?php endif;?>
<div class="dashboard-kpis">
 <a class="dashboard-kpi" href="<?=url('modules/students.php')?>"><span>Total estudiantes</span><b><?=(int)$stats['total']?></b><small><?=(int)$stats['activos']?> activos</small><i class="kpi-symbol">▦</i></a>
 <a class="dashboard-kpi" href="<?=url('modules/students.php?risk=Alto')?>"><span>Riesgo alto</span><b><?=(int)$stats['alto']?></b><small>Atención prioritaria</small><i class="kpi-symbol danger-symbol">!</i></a>
 <a class="dashboard-kpi" href="<?=url('modules/students.php?risk=Medio')?>"><span>Riesgo medio</span><b><?=(int)$stats['medio']?></b><small>En seguimiento</small><i class="kpi-symbol warning-symbol">◷</i></a>
 <a class="dashboard-kpi" href="<?=url('modules/reports.php')?>"><span>Atenciones del mes</span><b><?=$att?></b><small>Registradas</small><i class="kpi-symbol success-symbol">✓</i></a>
</div>
<div class="dashboard-charts">
 <section class="panel chart-panel"><div class="panel-head"><div><h3>Atenciones realizadas</h3><p>Evolución de los últimos seis meses</p></div><span class="chart-total"><?=array_sum($values)?> en el periodo</span></div>
 <div class="line-chart"><svg viewBox="0 0 530 195" role="img" aria-label="Atenciones por mes: <?=e(implode(', ',array_map(fn($m,$v)=>"$m $v",$months,$values)))?>" preserveAspectRatio="none"><line x1="40" y1="45" x2="490" y2="45"/><line x1="40" y1="107" x2="490" y2="107"/><line x1="40" y1="170" x2="490" y2="170"/><polygon points="<?=e($area)?>" class="chart-area"/><polyline points="<?=e($polyline)?>" class="chart-line"/><?php foreach($points as $point): $xy=explode(',',$point);?><circle cx="<?=$xy[0]?>" cy="<?=$xy[1]?>" r="4" class="chart-point"/><?php endforeach;?></svg><div class="chart-months"><?php foreach($months as $i=>$label):?><span title="<?=$values[$i]?> atenciones"><?=e($label)?></span><?php endforeach;?></div></div></section>
 <section class="panel chart-panel"><div class="panel-head"><div><h3>Estudiantes por programa</h3><p>Distribución de los registros</p></div></div><div class="program-bars"><?php foreach($programs as $p):?><div class="program-bar-row"><div class="program-bar-label"><strong><?=e($p['nombre'])?></strong><span><?=(int)$p['total']?></span></div><div class="program-track"><i style="width:<?=round((int)$p['total']/$maxProgram*100)?>%"></i></div></div><?php endforeach;?></div></section>
 <section class="panel chart-panel"><div class="panel-head"><div><h3>Niveles de riesgo</h3><p>Todos los estudiantes visibles</p></div></div><div class="risk-visual"><div class="risk-ring" style="--low:<?= $stats['total']?round($low/$stats['total']*100,2):0 ?>%;--medium:<?= $stats['total']?round((int)$stats['medio']/$stats['total']*100,2):0 ?>%"><div><b><?=(int)$stats['total']?></b><span>estudiantes</span></div></div><div class="risk-legend"><div><i class="dot bajo"></i>Bajo <b><?=$low?></b></div><div><i class="dot medio"></i>Medio <b><?=(int)$stats['medio']?></b></div><div><i class="dot alto"></i>Alto <b><?=(int)$stats['alto']?></b></div></div><div class="risk-side"><div class="risk-side-grid"><a href="<?=url('modules/students.php?risk=Alto')?>"><span>Prioridad alta</span><b><?=(int)$stats['alto']?></b><small>Revisar casos →</small></a><a href="<?=url('modules/students.php?risk=Medio')?>"><span>En observación</span><b><?=(int)$stats['medio']?></b><small>Ver estudiantes →</small></a><div><span>Asistencia media</span><b><?=(int)$extra['asistencia_media']?>%</b><small>Estudiantes activos</small></div><div><span>Alertas emocionales</span><b><?=(int)$extra['alertas_emocionales']?></b><small>Casos registrados</small></div></div></div></div><div class="risk-advice"><strong>Acciones de seguimiento</strong><p><b><?=count($alerts)?></b> casos prioritarios · <b><?=(int)$stats['medio']?></b> casos para observación</p><a href="<?=url('modules/students.php?risk=Alto')?>">Revisar alertas →</a></div></section>
</div>
<div class="dashboard-lower">
 <section class="panel"><div class="panel-head"><div><h3>Atenciones recientes</h3><p>Últimos registros de acompañamiento</p></div><a href="<?=url('modules/reports.php')?>">Ver reportes →</a></div><div class="table-wrap"><table><thead><tr><th>Estudiante</th><th>Tipo de atención</th><th>Responsable</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a class="student-link" href="<?=url('modules/student.php?id='.$r['student_id'])?>"><?=e($r['estudiante'])?></a></td><td><?=e($r['tipo'])?></td><td><?=e($r['responsable'])?></td><td><span class="badge badge-info"><?=e($r['estado'])?></span></td><td><?=e(format_date_es($r['fecha']))?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5" class="empty">Todavía no se han registrado atenciones.</td></tr><?php endif;?></tbody></table></div></section>
 <section class="panel"><div class="panel-head"><div><h3>Alertas prioritarias</h3><p>Riesgo alto con seguimiento pendiente</p></div><a href="<?=url('modules/students.php?risk=Alto')?>">Ver todos →</a></div><div class="priority-list"><?php foreach($alerts as $s):?><a href="<?=url('modules/student.php?id='.$s['id'])?>"><span class="priority-avatar">!</span><span><strong><?=e($s['estudiante'])?></strong><small><?=e($s['codigo'])?> · Asistencia <?=e((string)$s['asistencia'])?>%</small></span><span class="badge badge-danger">Alto</span></a><?php endforeach;?><?php if(!$alerts):?><p class="empty">No hay alertas de riesgo alto.</p><?php endif;?></div></section>
</div>
